using System;using RybinskTaxi;using RybinskTaxi.Data;
class Program {static void Main(){var page=new TaxiSearch();var group=SampleDataSource.GetGroup("Group-1");page.TestSearch("");if(page.SearchResults.Count!=group.Items.Count||page.TestCount!=page.SearchResults.Count)throw new Exception("Search count is stale");page.TestSearch("zzzz-no-match");if(page.SearchResults.Count!=0||page.TestCount!=0)throw new Exception("No-match count stale");page.TestSearch(group.Items[0].Title.ToUpperInvariant());if(page.SearchResults.Count==0||page.TestCount!=page.SearchResults.Count)throw new Exception("Case-insensitive title search");group.Items.Add(new SampleDataItem("synthetic",null,"",null,null,"",group));page.TestSearch("zzzz-no-match");if(page.SearchResults.Count!=0)throw new Exception("Null fields should not match");page.TestSearch(null);if(page.SearchResults.Count!=group.Items.Count||page.TestCount!=group.Items.Count)throw new Exception("Null query should clear search");Console.WriteLine("PASS: result counts, repeated queries, case-insensitive title search, missing fields and reset");}}
